      border-radius: 999px;
      background: var(--surface);
      color: var(--text);
      box-shadow: var(--shadow);
      transform: translateY(-200%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 4rem 1.25rem;
    }

    .support-shell {
      width: min(100%, 760px);
    }

    .hero {
      margin-bottom: 1.5rem;
      padding: 0 0.25rem;
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent);
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      font-size: 0.78rem;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.25rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .intro {
      margin: 0.75rem 0 0;
      max-width: 58ch;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .card {
      background: var(--surface);
      border: 1px solid rgba(151, 167, 190, 0.28);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: clamp(1.25rem, 3vw, 2rem);
    }

    form {
      display: grid;
      gap: 1rem;
    }

    .form-field {
      display: grid;
      gap: 0.5rem;
    }

    label {
      font-weight: 600;
      color: var(--text);
    }

    .required {
      color: var(--accent);
      margin-left: 0.15rem;
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--surface-alt);
      color: var(--text);
      padding: 0.95rem 1rem;
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
    }

    input::placeholder {
      color: #8a97a8;
    }

