    }

    button:active {
      transform: translateY(0);
    }

    @media (min-width: 640px) {
      form {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .form-field:nth-of-type(1),
      .form-field:nth-of-type(2),
      .form-field:nth-of-type(3),
      .actions {
        grid-column: 1 / -1;
      }
    }

