</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <div class="support-shell">
      <header class="hero">
        <p class="eyebrow">Support</p>
        <h1>Contact our support team</h1>
        <p class="intro">Send us your details and we’ll get back to you as soon as possible.</p>
      </header>

      <section class="card" aria-label="Support contact form">
        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
            <input id="full-name" name="full-name" type="text" autocomplete="name" required aria-describedby="full-name-error" />
            <p id="full-name-error" class="field-error" hidden></p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
            <input id="email-address" name="email-address" type="email" autocomplete="email" required aria-describedby="email-address-error" />
            <p id="email-address-error" class="field-error" hidden></p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number</label>
            <input id="phone-number" name="phone-number" type="tel" inputmode="tel" autocomplete="tel" aria-describedby="phone-number-hint phone-number-error" />
            <p id="phone-number-hint" class="field-hint">Optional. Enter a number in a format like +1 555 123 4567.</p>
            <p id="phone-number-error" class="field-error" hidden></p>
          </div>

          <div class="actions">
            <button type="submit">Submit request</button>
          </div>
        </form>
      </section>
    </div>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const fields = [
      {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        message: 'Please enter your full name.'
      },
      {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        message: 'Please enter a valid email address.'
      },
      {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        message: 'Please use a valid phone number, such as +1 555 123 4567.'
      }
    ];

    const phonePattern = /^(?=.*\d)[+()\d\s.-]{7,}$/;

    function clearError(field) {
      field.input.removeAttribute('aria-invalid');
      field.error.textContent = '';
      field.error.hidden = true;
    }

    function setError(field, message) {
      field.input.setAttribute('aria-invalid', 'true');
      field.error.textContent = message;
      field.error.hidden = false;
    }

    function validateField(field) {
      const value = field.input.value.trim();

      if (field.input.required && !value) {
        setError(field, field.message);
        return false;
      }

      if (field.input.type === 'email' && value && !field.input.checkValidity()) {
        setError(field, field.message);
        return false;
      }

      if (field.input.id === 'phone-number' && value && !phonePattern.test(value)) {
        setError(field, field.message);
        return false;
      }

      clearError(field);
      return true;
    }

    fields.forEach((field) => {
      field.input.addEventListener('input', () => validateField(field));
      field.input.addEventListener('blur', () => {
        if (field.input.value.trim()) {
          validateField(field);
        } else {
          clearError(field);
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const invalidField = fields.find((field) => !validateField(field));

      if (invalidField) {
        invalidField.input.focus();
        return;
      }

      form.reset();
      fields.forEach(clearError);
    });
  </script>
</body>
</html>
